import {useState} from 'react';
import {Alert,Image,Pressable,ScrollView,StyleSheet,Text,View} from '@/platform/react-native';
import {router,useLocalSearchParams} from '@/router';
import {useMutation,useQueryClient} from '@tanstack/react-query';
import {Ionicons} from '@/platform/icons';
import * as ImagePicker from '@/platform/image-picker';
import {api} from '@/lib/api';
import {AmountInput,Button,Card,Header,Input,Muted,Screen,ToggleSwitch as Switch,useAppTheme} from '@/components/UI';
import {amountNumber} from '@/lib/money';
const types=['FOR_SALE','FREE','WANTED','SERVICES','RENTALS','JOBS'] as const;const conditions=['NEW','LIKE_NEW','GOOD','FAIR','NOT_APPLICABLE'] as const;const deliveries=['MEETUP','DELIVERY'] as const;const contacts=['IN_APP','PHONE','WHATSAPP'] as const;
async function upload(uri:string,index:number){const fd=new FormData();fd.append('file',{uri,name:`listing-${Date.now()}-${index}.jpg`,type:'image/jpeg'} as any);return (await api.post('/media/upload',fd,{headers:{'Content-Type':'multipart/form-data'}})).data.url as string}
export default function PostMarketplaceItem(){
 const{id}=useLocalSearchParams<{id:string}>();const{palette}=useAppTheme();const qc=useQueryClient();const[photos,setPhotos]=useState<string[]>([]);const[type,setType]=useState<(typeof types)[number]>('FOR_SALE');const[title,setTitle]=useState('');const[condition,setCondition]=useState<(typeof conditions)[number]>('GOOD');const[price,setPrice]=useState('');const[description,setDescription]=useState('');const[area,setArea]=useState('');const[delivery,setDelivery]=useState<(typeof deliveries)[number]>('MEETUP');const[contact,setContact]=useState<(typeof contacts)[number]>('IN_APP');const[negotiable,setNegotiable]=useState(false);
 const create=useMutation({mutationFn:async()=>{const imageUrls=await Promise.all(photos.map(upload));return api.post(`/communities/${id}/marketplace`,{listingType:type,title:title.trim(),description:description.trim(),price:type==='FREE'||!price?undefined:amountNumber(price),currency:'NGN',area:area.trim(),imageUrl:imageUrls[0],imageUrls,itemCondition:condition,deliveryOption:delivery,contactPreference:contact,isNegotiable:negotiable})},onSuccess:()=>{qc.invalidateQueries({queryKey:['marketplace',id]});Alert.alert('Item posted','Your listing is now visible to community members.',[{text:'View Marketplace',onPress:()=>router.replace(`/community/${id}/marketplace` as never)}])},onError:(e:any)=>Alert.alert('Unable to post item',e.response?.data?.message||'Please review the form and try again.')});
 async function choosePhotos(){const permission=await ImagePicker.requestMediaLibraryPermissionsAsync();if(!permission.granted){Alert.alert('Photo permission required','Allow photo access to add listing images.');return}const remaining=6-photos.length;if(remaining<=0)return;const result=await ImagePicker.launchImageLibraryAsync({mediaTypes:['images'],quality:.82,allowsMultipleSelection:true,selectionLimit:remaining});if(!result.canceled)setPhotos(current=>[...current,...result.assets.map(x=>x.uri)].slice(0,6))}
 const valid=title.trim().length>=2&&description.trim().length>=3&&area.trim().length>=2&&(type==='FREE'||type==='WANTED'||price.length>0);
 return <Screen scroll contentStyle={s.page}><Header page title="Post Item" subtitle="Create a real listing for members of this community."/><View style={s.sectionHead}><View><Text style={[s.heading,{color:palette.text}]}>Add Photos</Text><Muted>Add up to 6 photos. The first photo is the cover.</Muted></View><Text style={{color:palette.primary,fontWeight:'900'}}>{photos.length}/6</Text></View><ScrollView horizontal showsHorizontalScrollIndicator={false} contentContainerStyle={s.photos}>{photos.map((uri,index)=><View key={`${uri}-${index}`} style={[s.photo,{borderColor:palette.border}]}><Image source={{uri}} style={s.photoImage}/>{index===0?<View style={[s.cover,{backgroundColor:palette.primary}]}><Text style={s.coverText}>Cover</Text></View>:null}<Pressable accessibilityLabel={`Remove photo ${index+1}`} onPress={()=>setPhotos(x=>x.filter((_,i)=>i!==index))} style={s.remove}><Ionicons name="close-circle" size={25} color={palette.danger}/></Pressable></View>)}{photos.length<6?Array.from({length:6-photos.length}).map((_,index)=><Pressable key={`empty-${index}`} accessibilityRole="button" accessibilityLabel="Add listing photo" onPress={()=>void choosePhotos()} style={[s.photo,s.emptyPhoto,{borderColor:palette.border,backgroundColor:palette.surface}]}><Ionicons name={photos.length?'add':'camera-outline'} size={31} color={palette.primary}/>{index===0?<Text style={{color:palette.primary,fontWeight:'900'}}>Add Photo</Text>:null}</Pressable>):null}</ScrollView><Text style={[s.heading,{color:palette.text}]}>Basic Information</Text><Choice values={types} value={type} set={setType} palette={palette}/><Input placeholder="Item title *" value={title} onChangeText={setTitle}/><Text style={[s.label,{color:palette.text}]}>Condition</Text><Choice values={conditions} value={condition} set={setCondition} palette={palette}/>{type!=='FREE'&&type!=='WANTED'?<AmountInput placeholder="Price (NGN) *" value={price} onChangeText={setPrice}/>:null}<Input placeholder="Description *" value={description} onChangeText={setDescription} multiline maxLength={1000}/><Muted style={s.count}>{description.length}/1000</Muted><Input placeholder="Location or area *" value={area} onChangeText={setArea}/><Text style={[s.heading,{color:palette.text}]}>Delivery Option</Text><Choice values={deliveries} value={delivery} set={setDelivery} palette={palette}/><Text style={[s.heading,{color:palette.text}]}>Contact Preference</Text><Choice values={contacts} value={contact} set={setContact} palette={palette}/><Card style={s.toggle}><View style={{flex:1}}><Text style={[s.toggleTitle,{color:palette.text}]}>Mark as negotiable</Text><Muted>Buyers may discuss the price with you.</Muted></View><Switch accessibilityLabel="Mark listing as negotiable" value={negotiable} onValueChange={setNegotiable} trackColor={{false:palette.border,true:palette.primary}}/></Card><Button title="Review & Post" icon="checkmark-circle-outline" variant="success" loading={create.isPending} disabled={!valid||create.isPending} onPress={()=>create.mutate()}/></Screen>
}
function Choice<T extends string>({values,value,set,palette}:{values:readonly T[];value:T;set:(value:T)=>void;palette:any}){return <View style={s.choices}>{values.map(item=><Pressable key={item} accessibilityRole="button" accessibilityState={{selected:value===item}} onPress={()=>set(item)} style={[s.choice,{borderColor:value===item?palette.primary:palette.border,backgroundColor:value===item?palette.primarySoft:palette.surface}]}><Text numberOfLines={1} adjustsFontSizeToFit style={{color:value===item?palette.primary:palette.text,fontWeight:'800',fontSize:12}}>{item.replaceAll('_',' ')}</Text></Pressable>)}</View>}
const s=StyleSheet.create({page:{width:'100%',maxWidth:760,alignSelf:'center',paddingBottom:140},sectionHead:{flexDirection:'row',alignItems:'flex-end',justifyContent:'space-between',gap:10},heading:{fontSize:18,fontWeight:'900',marginTop:15,marginBottom:7},label:{fontSize:14,fontWeight:'800',marginBottom:7},photos:{gap:9,paddingVertical:13,paddingRight:12},photo:{width:118,height:126,borderWidth:1.5,borderRadius:14,overflow:'hidden',position:'relative'},emptyPhoto:{borderStyle:'dashed',alignItems:'center',justifyContent:'center',gap:6},photoImage:{width:'100%',height:'100%'},cover:{position:'absolute',left:0,top:0,paddingHorizontal:8,paddingVertical:4,borderBottomRightRadius:9},coverText:{color:'#fff',fontWeight:'900',fontSize:10},remove:{position:'absolute',right:3,top:3,width:34,height:34,alignItems:'center',justifyContent:'center'},choices:{flexDirection:'row',flexWrap:'wrap',gap:8,marginBottom:13},choice:{minHeight:44,borderWidth:1.5,borderRadius:12,paddingHorizontal:13,alignItems:'center',justifyContent:'center',minWidth:76},count:{textAlign:'right',marginTop:-9,marginBottom:10},toggle:{flexDirection:'row',alignItems:'center',gap:12},toggleTitle:{fontSize:15,fontWeight:'900'}});
